// ============== Components ==============

function Icon(props: { name: keyof typeof Icons; class?: string; size?: string }) {
  const sizeClass = () => {
    switch (props.size) {
      case 'xs': return 'w-3 h-3';
      case 'sm': return 'w-5 h-5';
      case 'lg': return 'w-8 h-8';
      case 'xl': return 'w-12 h-12';
      default: return 'w-6 h-6';
    }
  };

  return (
    <div class={`bolh-icon inline-flex items-center justify-center shrink-0 ${sizeClass()} ${props.class || ''}`}>
      {(() => {
        const factory = Icons[props.name];
        return factory ? factory() : Icons.alertCircle();
      })()}
    </div>
  );
}

